// CSD_RATIONALE_BEGIN
// Forced-span CSD for symbolic GSM reasoning.
//
// The dominant failure mode in attempt 1 was that the model consumed all 900
// steps on free reasoning text without ever emitting "<<", leaving 21/49
// examples with no valid span and 6/49 that opened "<<" right at budget end.
//
// Fix: cap unconstrained reasoning at (maxSteps - 200) steps via a Phase-1
// loop.  If "<<" has not appeared by that budget, Phase 2 calls
// OpenConstrainedSpan to force the span open, guaranteeing the span lifecycle
// starts.  Phase 3 runs AdaptiveConstrainedStep per token and calls
// CloseConstrainedSpan as soon as the parser accepts the content, guaranteeing
// ">>" is emitted before the step budget runs out.
//
// Task guidance is kept concise and does not mention the literal characters
// "<<" or ">>" inside the reasoning instructions, avoiding the "instructions
// say to wrap in <<" confusion that caused malformed_constrained_content
// failures in attempt 1.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   Phase 1 (UnconstrainedStep): flips insideConstrainedOut to true only when
//     RenderedEndsWith(generated,"<<"); currentConstrainedOut is reset to [],
//     which is valid by the method precondition parser.IsValidPrefix([]).
//     Otherwise the branch is unconstrained and the implication is vacuously
//     true or state is unchanged.
//   Phase 2 (OpenConstrainedSpan): resets currentConstrainedOut to []; same
//     argument applies.
//   Phase 3 close path (CloseConstrainedSpan): sets insideConstrainedOut :=
//     false and currentConstrainedOut := [], making the implication vacuously
//     true.
//   Phase 3 token path (AdaptiveConstrainedStep + AppendConstrainedToken):
//     AdaptiveConstrainedStep returns EOS or a token t such that
//     parser.IsValidPrefix(currentConstrainedOut + [t]); AppendConstrainedToken
//     updates currentConstrainedOut to that valid extension.
//
// progress: |generated| <= |generatedPrefix| + steps
//   Phase 1: each UnconstrainedStep appends at most one non-EOS token and
//     increments steps by 1; bound preserved every iteration.
//   Phase 2: OpenConstrainedSpan appends exactly one token ("<<") and steps
//     grows by 1; bound preserved.
//   Phase 3 close: CloseConstrainedSpan appends exactly one token (">>") and
//     steps grows by 1; bound preserved.
//   Phase 3 token: AdaptiveConstrainedStep consumes 1 step; AppendConstrainedToken
//     appends 1 visible token; net growth at most 1 per iteration; bound preserved.
//   cost = steps; loop guards ensure steps <= maxSteps throughout.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve using the symbolic variables given in the problem. " +
  "Work step by step, identifying quantities and their relationships. " +
  "End your response with exactly: The final answer is <<expr>> " +
  "where expr is a complete symbolic expression built from the problem " +
  "variables using only +, -, /, //, %, (), and int().");

var prefixBudget: nat := if maxSteps > 200 then maxSteps - 200 else maxSteps / 2;
var steps: nat := 0;

// Phase 1: unconstrained reasoning until "<<" appears or prefixBudget exhausted
while steps < prefixBudget && !insideConstrainedOut
  invariant 0 <= steps <= prefixBudget
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases prefixBudget - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    insideConstrainedOut := true;
    currentConstrainedOut := [];
  }
}

// Phase 2: force the constrained span open if it was not naturally opened
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: constrained generation until the parser accepts the span as complete
while steps < maxSteps && insideConstrainedOut
  invariant steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut,
      validTokenGroups, 4.0, 12, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    var ag, ai, ac := helpers.AppendConstrainedToken(
      lm, parser, generated, currentConstrainedOut, next
    );
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  }
}

cost := steps;

